export type WorldState = Record<string, string>;

const initialState: WorldState = {
  Osk: "nim",
  Fen: "nim",
};

const copyState = (state: WorldState): WorldState => ({ ...state });

const invalidTransition = (operationDisplayName: string): {
  success: false;
  error: string;
} => ({
  success: false,
  error: `Cannot apply operation: ${operationDisplayName}`,
});

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return copyState(initialState);
  },

  applyOperation(
    state: WorldState,
    operationDisplayName: string
  ): { success: true; newState: WorldState } | { success: false; error: string } {
    switch (operationDisplayName) {
      case "advanceOsk":
        if (state.Osk !== "nim") {
          return invalidTransition(operationDisplayName);
        }
        return {
          success: true,
          newState: { ...state, Osk: "pex" },
        };

      case "advanceFen":
        if (state.Fen !== "nim") {
          return invalidTransition(operationDisplayName);
        }
        return {
          success: true,
          newState: { ...state, Fen: "pex" },
        };

      case "advanceOskFen":
        if (state.Osk !== "nim" || state.Fen !== "nim") {
          return invalidTransition(operationDisplayName);
        }
        return {
          success: true,
          newState: { ...state, Osk: "pex", Fen: "pex" },
        };

      default:
        return invalidTransition(operationDisplayName);
    }
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    return state[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return copyState(state);
  },
};
